from pathlib import Path
import json,hashlib
from collections import defaultdict
root=Path('/tmp/research_history');rows=[]
local=defaultdict(list)
for p in sorted(root.glob('screen_all_*.log')):
 try:
  first=int(p.stem.split('_')[2])
 except (ValueError,IndexError):continue
 if first<85:continue
 for line in p.read_text().splitlines():
  z=line.split()
  if len(z)==13 and z[2]=='time':local[z[1]].append({'case':z[0],'time':float(z[3]),'nrmse':float(z[5]),'rho':float(z[7]),'top':float(z[9]),'valid':z[12]=='True','log':p.name})
  elif len(z)==12 and z[2]=='time':local[z[1]].append({'case':z[0],'time':float(z[3]),'nrmse':float(z[5]),'rho':float(z[7]),'top':float(z[9]),'valid':z[11]=='True','log':p.name})
for p in sorted(root.glob('[0-9][0-9][0-9]_*/method.py')):
 n=int(p.parent.name[:3])
 if n<85:continue
 row={'variant':p.parent.name,'source_sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 ls=local.get(p.parent.name)
 if ls:row['local']={'cases':len(ls),'passes':sum(z['valid'] for z in ls),'worst_nrmse':max(z['nrmse'] for z in ls),'min_rho':min(z['rho'] for z in ls),'min_top':min(z['top'] for z in ls),'mean_time':sum(z['time'] for z in ls)/len(ls),'logs':list(dict.fromkeys(z['log'] for z in ls))}
 report=p.parent/'result.json'
 if report.exists():
  z=json.loads(report.read_text());row['formal']={k:z[k] for k in ['status','raw_metric','score','quality_valid','method_sha256']}
  row['formal']['cases']=len(z['cases'])
 rows.append(row)
(root/'episode_3_index.json').write_text(json.dumps(rows,indent=2)+'\n')
for z in rows:
 if 'formal' in z:print(z['variant'],z['formal'])
PY
